head.b:skin:
/*<Variable name="color.primary" description="Primary Color" type="color" default="#0D47A1"/>*/
/*<Variable name="color.secondary" description="Secondary Color" type="color" default="#EF6C00"/>*/
/*<Variable name="color.bg.light" description="Background (Light)" type="color" default="#F5F5F5"/>*/
/*<Variable name="color.bg.dark" description="Background (Dark)" type="color" default="#121212"/>*/
/*<Variable name="color.text.light" description="Text (Light)" type="color" default="#111111"/>*/
/*<Variable name="color.text.dark" description="Text (Dark)" type="color" default="#EAEAEA"/>*/
/*<Variable name="card.bg.light" description="Card BG (Light)" type="color" default="#FFFFFF"/>*/
/*<Variable name="card.bg.dark" description="Card BG (Dark)" type="color" default="#1E1E1E"/>*/

:root {
  --color-primary: $(color.primary);
  --color-secondary: $(color.secondary);
  --color-bg: $(color.bg.light);
  --color-text: $(color.text.light);
  --card-bg: $(card.bg.light);
  --color-border: #e0e0e0;
}
html.theme-dark {
  --color-bg: $(color.bg.dark);
  --color-text: $(color.text.dark);
  --card-bg: $(card.bg.dark);
  --color-border: #333;
}
body { font-family: 'Tajawal', sans-serif; background-color: var(--color-bg); color: var(--color-text); margin: 0; line-height: 1.7; font-size: 16px; direction: rtl; }
.header-container, .footer-container { background-color: var(--card-bg); border-bottom: 1px solid var(--color-border); padding: 15px; }
.footer-container { border-bottom: 0; border-top: 1px solid var(--color-border); margin-top: 20px; text-align: center; }
.header-inner { max-width: 1200px; margin: 0 auto; display: flex; justify-content: space-between; align-items: center; }
.main-container { max-width: 1200px; margin: 20px auto; display: flex; flex-wrap: wrap; gap: 20px; }
.content-area { flex: 1 1 70%; min-width: 0; }
.sidebar-area { flex: 1 1 25%; min-width: 0; }
.post { background-color: var(--card-bg); border: 1px solid var(--color-border); margin-bottom: 20px; border-radius: 5px; overflow: hidden; }
.post-content { padding: 25px; }
.post-title a { font-size: 1.8em; color: var(--color-text); font-weight: bold; text-decoration: none; }
.post-body { margin-top: 15px; }
.no-posts-message { background-color: var(--card-bg); border: 1px solid var(--color-border); border-radius: 5px; padding: 40px; text-align: center; }
.theme-toggle { cursor: pointer; padding: 8px 12px; border: 1px solid var(--color-border); border-radius: 5px; }

body.script:
//
document.addEventListener('DOMContentLoaded', function() {
    const themeToggle = document.getElementById('theme-toggle');
    if(themeToggle) {
        const htmlEl = document.documentElement;
        const currentTheme = localStorage.getItem('theme');
        if (currentTheme) { htmlEl.classList.add(currentTheme); }
        themeToggle.addEventListener('click', () => {
            htmlEl.classList.toggle('theme-dark');
            localStorage.setItem('theme', htmlEl.classList.contains('theme-dark') ? 'theme-dark' : '');
        });
    }
});
//
